1	/** The MHPCO's shared vocabulary for what a policy covers. */
2	
3	export interface Customer {
4	  readonly yearsWithMHPCO: number;
5	}
6	
7	export interface Item {
8	  readonly type: string;
9	  readonly material?: string;
10	  readonly enchantment?: number;
11	  readonly cursed?: boolean;
12	}
13	
14	/** What insured items contribute to a premium, before policy-wide modifiers. */
15	export interface ItemPricing {
16	  /** Sum of item base premiums -- the policy base premium. */
17	  readonly basePremium: number;
18	  /** Item-specific risk surcharges, each on its own item's base premium. */
19	  readonly riskSurcharges: number;
20	}
21	
22	/** An item that contributes nothing -- the identity for combining pricings. */
23	export const NO_PRICING: ItemPricing = { basePremium: 0, riskSurcharges: 0 };
24	
25	/**
26	 * Pricings combine by adding each contribution separately: base premiums
27	 * accumulate into the policy base premium, and risk surcharges accumulate
28	 * alongside it, because policy-wide modifiers scale only the former.
29	 */
30	export function combinedPricing(
31	  left: ItemPricing,
32	  right: ItemPricing,
33	): ItemPricing {
34	  return {
35	    basePremium: left.basePremium + right.basePremium,
36	    riskSurcharges: left.riskSurcharges + right.riskSurcharges,
37	  };
38	}
