1	import type { Item, ItemPricing } from "./policy.js";
2	import { NO_PRICING, combinedPricing } from "./policy.js";
3	import { riskSurchargeOf } from "./risk-surcharge.js";
4	
5	/** The MHPCO price list for main items: base premium in G per item type. */
6	const MAIN_ITEM_BASE_PREMIUMS: Readonly<Record<string, number>> = {
7	  sword: 100,
8	  amulet: 60,
9	  staff: 80,
10	  potion: 40,
11	};
12	
13	function mainItemBasePremiumOf(item: Item): number {
14	  return MAIN_ITEM_BASE_PREMIUMS[item.type] ?? 0;
15	}
16	
17	/**
18	 * What one main item contributes: the price list's base premium, and the
19	 * item's own risk surcharges, which scale that same base premium.
20	 */
21	function priceMainItem(item: Item): ItemPricing {
22	  const basePremium = mainItemBasePremiumOf(item);
23	  return {
24	    basePremium,
25	    riskSurcharges: riskSurchargeOf(item, basePremium),
26	  };
27	}
28	
29	export function priceMainItems(mainItems: readonly Item[]): ItemPricing {
30	  return mainItems.reduce<ItemPricing>(
31	    (total, item) => combinedPricing(total, priceMainItem(item)),
32	    NO_PRICING,
33	  );
34	}
