1	import { componentsBasePremium, isComponent } from "./component-block.js";
2	import { priceMainItems } from "./main-item.js";
3	import type { Item, ItemPricing } from "./policy.js";
4	import { combinedPricing } from "./policy.js";
5	
6	/**
7	 * Components are insured at a flat rate and carry no item-specific risk:
8	 * a rune has neither an enchantment level nor a material to be cursed.
9	 */
10	function priceComponents(components: readonly Item[]): ItemPricing {
11	  return {
12	    basePremium: componentsBasePremium(components),
13	    riskSurcharges: 0,
14	  };
15	}
16	
17	/**
18	 * Each item is priced by the pricing policy that governs its kind:
19	 * components may form blocks, main items follow the price list.
20	 */
21	export function priceItems(items: readonly Item[]): ItemPricing {
22	  return combinedPricing(
23	    priceMainItems(items.filter((item) => !isComponent(item))),
24	    priceComponents(items.filter(isComponent)),
25	  );
26	}
