1	import type { Item } from "./policy.js";
2	
3	/** Components such as runes and moonstones share one base premium. */
4	const COMPONENT_BASE_PREMIUM = 25;
5	
6	const COMPONENT_TYPES: readonly string[] = ["rune", "moonstone"];
7	
8	/** A building block of alike components is offered at a special premium. */
9	const COMPONENT_BLOCK_SIZE = 3;
10	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
11	
12	export function isComponent(item: Item): boolean {
13	  return COMPONENT_TYPES.includes(item.type);
14	}
15	
16	/** Components count as "alike" -- and so may form a block -- per item type. */
17	function alikeGroupSizes(components: readonly Item[]): readonly number[] {
18	  const sizes = new Map<string, number>();
19	  for (const component of components) {
20	    sizes.set(component.type, (sizes.get(component.type) ?? 0) + 1);
21	  }
22	  return [...sizes.values()];
23	}
24	
25	/**
26	 * A block requires *exactly* the block size: 4 or 7 alike components are
27	 * priced per component, not as blocks plus a remainder.
28	 */
29	function alikeGroupBasePremium(groupSize: number): number {
30	  if (groupSize === COMPONENT_BLOCK_SIZE) {
31	    return COMPONENT_BLOCK_BASE_PREMIUM;
32	  }
33	  return groupSize * COMPONENT_BASE_PREMIUM;
34	}
35	
36	export function componentsBasePremium(components: readonly Item[]): number {
37	  return alikeGroupSizes(components).reduce(
38	    (sum, groupSize) => sum + alikeGroupBasePremium(groupSize),
39	    0,
40	  );
41	}
