/**
 * Every insured item is either a component or a main item -- the two kinds
 * the MHPCO prices by different rules, and between them they cover
 * everything a policy can contain.
 */
function partitionByPricingKind(items: readonly Item[]): {
  readonly components: readonly Item[];
  readonly mainItems: readonly Item[];
} {
  const components: Item[] = [];
  const mainItems: Item[] = [];
